# Edit a claim's amount, date, note and reference. Validate first so a bad amount or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: locked
# A claim whose editor another user has open is a 409 and writes nothing.
locked:
  class: net.officefloor.hq.app.claim.CheckClaimLock
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing. An edit keeps its due-by,
# so it cannot move it into one.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: ref
# A reference another claim on the sheet has (regardless of case) is a 400 and writes nothing.
ref:
  class: net.officefloor.hq.app.claim.CheckClaimRef
  govern: [ transaction ]
  next: correction
# A correction (a negative amount) must name a settled claim of the same person: else a 400.
correction:
  class: net.officefloor.hq.app.claim.CheckCorrection
  govern: [ transaction ]
  next: retired
# Nor may an edit date it after its person's retirement date.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: release
# A saved edit closes the claim's editor: its lock is released.
release:
  class: net.officefloor.hq.app.claim.ReleaseClaimLock
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Open a claim's editor: locks the claim for the user until the editor is saved or cancelled, or the
# sheet's today changes. A claim that cannot be edited (not a draft, due by a date inside a closed period)
# or whose editor another user has open is a 409 and takes no lock.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: lock
lock:
  class: net.officefloor.hq.app.claim.LockClaim
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Applies an edit to a draft, recording the signed-in user as the one who last edited it. */
public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Sheet sheet, @Val Claim claim, HttpServletRequest request)
            throws InvalidClaimStatusException {
        claim.checkEditable();
        claim.setAmount(input.amount());
        claim.setDate(input.date() == null ? sheet.today() : input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setEditedBy(Audit.user(request));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim whose editor another user has open, before anything is written. */
public class CheckClaimLock {
    public void check(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            HttpServletRequest request) throws ClaimLockedException {
        if (repository.lockedByOther(claim, Audit.user(request), sheet.today())) {
            throw new ClaimLockedException(String.valueOf(claim.getId()));
        }
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Opens the claim's editor for the user: only a draft may be edited, and not while another user
 * has its editor open (on the sheet's today). Any other editor the user had open on the same
 * person's claims is released, as the person's form edits one claim at a time.
 */
public class LockClaim {
    public void lock(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository,
            HttpServletRequest request) throws InvalidClaimStatusException, ClaimLockedException {
        claim.checkEditable();
        String user = Audit.user(request);
        if (!repository.lock(claim, user, sheet.today())) throw new ClaimLockedException(String.valueOf(claim.getId()));
        repository.unlockOthers(claim, user);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved claim. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditClaimEdited {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_EDITED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body)
            throws InvalidClaimException {
        body.set(ClaimInput.from(request));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim as the screen sends it, to add or to edit: an amount (up to two decimals; negative only
 * for a correction), a date (yyyy-MM-dd, or blank for the sheet's entry date while it is set, else its today), a note (may be empty)
 * and, for a correction, the number of the settled claim it corrects (blank otherwise), and its
 * external reference (blank for none), and its tags: comma separated (blank for none).
 */
public record ClaimRequest(String amount, String date, String note, String corrects, String ref, String tags) {
    public ClaimRequest(String amount, String date, String note, String corrects, String ref) {
        this(amount, date, note, corrects, ref, "");
    }
}

