package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;

/**
 * A validated claim request. {@code date} is null when left blank: the sheet's entry date while it is set, else its today.
 * {@code corrects} is the number of the claim a correction (a negative amount) corrects; null for
 * any other claim. {@code ref} is its external reference, trimmed; null when left blank. {@code tags} are its
 * tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none are given.
 */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");

    /** A claim request checked by the claim form's rules. */
    public static ClaimInput from(ClaimRequest request) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) throw new InvalidClaimException("An amount is required");
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("An amount is a number with up to two decimals");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("A date is yyyy-MM-dd");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) throw new InvalidClaimException("A note is at most 1000 characters");
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (rawCorrects.isEmpty()) {
                throw new InvalidClaimException("A negative amount is a correction: name the claim it corrects");
            }
            if (!NUMBER.matcher(rawCorrects).matches()) {
                throw new InvalidClaimException("A correction names a claim by its number");
            }
            corrects = rawCorrects;
        } else if (!rawCorrects.isEmpty()) {
            throw new InvalidClaimException("Only a negative amount corrects a claim");
        }
        String ref = request.ref() == null ? "" : request.ref().trim();
        if (ref.length() > 200) throw new InvalidClaimException("A reference is at most 200 characters");
        String tags = tags(request.tags());
        if (tags != null && tags.length() > 2000) throw new InvalidClaimException("Tags are at most 2000 characters");
        return new ClaimInput(value, date, note, corrects, ref.isEmpty() ? null : ref, tags);
    }

    /** Comma separated tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none. */
    static String tags(String raw) {
        if (raw == null) return null;
        java.util.TreeSet<String> tags = new java.util.TreeSet<>();
        for (String tag : raw.split(",")) {
            String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
            if (!t.isEmpty()) tags.add(t);
        }
        return tags.isEmpty() ? null : String.join(",", tags);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;

/**
 * A claim, as the screen reads it: its amount with two decimals, its date as yyyy-MM-dd and its
 * status, its number ("" when it has none), and its due as fixed when it was settled ("" while
 * its due is live), and who opened it ("" until it is opened); whether its person's last
 * statement bound it, and the figure it was bound to ("" when not stated, n/a when it had none);
 * and the number of the claim it corrects ("" when it is no correction); and the date its figures
 * round by (a correction's is the date of the claim it corrects); and its due-by as yyyy-MM-dd, fixed
 * when it was made; and its status log, oldest first, one line per status it has had as
 * {@code <STATUS> by <user> on <date> due=<due>}; and the date it is deferred until as yyyy-MM-dd
 * ("" when it was never deferred; it is deferred only while OPEN and the sheet's today is before it);
 * and how many proofs it has had added; and the number of the claim it was split off ("" when none);
 * and the user whose open editor locks it on the sheet's today ("" when no one's does);
 * and whether it was added while its period was soft-closed; and the last sheet's today it was reminded
 * as yyyy-MM-dd ("" when never); and its external reference ("" when none); and its tags, sorted (none: empty); and the reason it was voided with ("" when none); and its comments, oldest first, as
 * {@code <user> on <date>: <text>}; and the number of the bulk settle batch that settled it ("" when none did).
 */
public record ClaimResponse(String id, String personId, String amount, String date, String note,
        String status, String number, String due, String openedBy, boolean stated,
        String statedDue, String corrects, String roundDate, String dueBy, List<String> log, String deferredUntil,
        int proofs, String splitFrom, String lockedBy, boolean lateEntry, String remindedOn, String ref,
        List<String> tags, String voidReason, List<String> comments, String batch) {
    public static ClaimResponse from(Claim claim) {
        return from(claim, List.of(), List.of());
    }

    public static ClaimResponse from(Claim claim, List<String> log, List<String> comments) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(),
                claim.getNumber() == null ? "" : claim.getNumber(),
                claim.getSettledDue() == null ? "" : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(),
                claim.isStated(),
                !claim.isStated() ? "" : claim.getStatedDue() == null ? "n/a" : claim.getStatedDue().toPlainString(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundDate().toString(), claim.getDueBy().toString(), log,
                claim.getDeferredUntil() == null ? "" : claim.getDeferredUntil().toString(),
                claim.getProofs(),
                claim.getSplitFrom() == null ? "" : claim.getSplitFrom(),
                claim.getLockedBy() == null ? "" : claim.getLockedBy(),
                claim.isLateEntry(),
                claim.getRemindedOn() == null ? "" : claim.getRemindedOn().toString(),
                claim.getRef() == null ? "" : claim.getRef(),
                claim.tagList(),
                claim.getVoidReason() == null ? "" : claim.getVoidReason(),
                comments,
                claim.getSettleBatch() == null ? "" : String.valueOf(claim.getSettleBatch()));
    }
}
